    whyP2: 'Como mãe de três filhos, SungHa observou que cada criança carregava um temperamento claramente diferente desde o nascimento — ritmos, sensibilidades e formas de se relacionar com o mundo distintos. Os conselhos tradicionais de criação tratavam todas as crianças de forma igual. O Saju não.',
