    whyP2: 'En tant que mère de trois enfants, SungHa a observé que chaque enfant portait un tempérament nettement différent dès la naissance — des rythmes, des sensibilités et des façons d\'interagir avec le monde différents. Les conseils parentaux traditionnels traitaient tous les enfants de la même manière. Le Saju, non.',
    whyP3: 'Après avoir obtenu sa certification de Conseillère en Psychologie Myeongri Niveau 1 — une qualification qui relie les Quatre Piliers traditionnels à la psychologie du conseil moderne — et avoir complété un Master en Sciences de la Prise de Décision et Analytique Appliquée, SungHa a créé SoMyung pour rendre ce savoir ancestral accessible, structuré et pratique pour les parents modernes.',
